import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (1, 'admin', 'admin@corp.internal', 'superadmin', 'sk-prod-9f8a7b6c5d4e3f2a1b')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key) VALUES (2, 'svc-deploy', 'deploy@corp.internal', 'deployer', 'sk-prod-deploy-x7y8z9')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Build query with validated field name but injectable value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID. API key is only shown to admins."""
    requesting_role = request.headers.get('X-User-Role', 'user')
    db = get_db()

    if requesting_role == 'superadmin':
        user = db.execute('SELECT * FROM users WHERE id = ?', (user_id,)).fetchone()
    else:
        user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()

    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/api/health', methods=['GET'])
def health():
    try:
        db = get_db()
        db.execute('SELECT 1')
        return jsonify({'status': 'healthy', 'db': 'connected'})
    except:
        return jsonify({'status': 'degraded', 'db': 'disconnected'}), 503

@app.before_request
def log_request():
    """Audit logging for compliance."""
    if request.endpoint and request.endpoint != 'health':
        try:
            db = get_db()
            db.execute(
                'INSERT INTO audit_log (action, actor) VALUES (?, ?)',
                (f"{request.method} {request.path}", request.remote_addr)
            )
            db.commit()
        except:
            pass

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
